    col_pts={c:[r for r in range(h) if grid[r][c]==fg] for c in range(w)}
    core_rows={r for r,xs in row_pts.items() if len(xs)>=4}
    core_cols={c for c,ys in col_pts.items() if len(ys)>=4}
    # Add 3-mark rows/cols only when they contain a foreground point outside core-axis intersections.
